import { useEffect, useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { EdgesGeometry, IcosahedronGeometry, TorusGeometry } from 'three';

// Six small silhouettes at the edges leave the disk and section content readable.
const OBJECTS = [
  [-0.39, 0.27, 0.011], [0.37, 0.35, 0.009], [-0.32, -0.34, 0.013],
  [0.4, -0.28, 0.01], [-0.12, 0.41, 0.008], [0.19, -0.41, 0.009],
];

export function FloatingObjects({ frozen = false }) {
  const root = useRef(null);
  const elapsed = useRef(0);
  const shapes = useMemo(() => {
    const solid = [new IcosahedronGeometry(1, 0), new TorusGeometry(0.8, 0.18, 6, 12)];
    return solid.map((geometry) => ({ geometry, edges: new EdgesGeometry(geometry, 25) }));
  }, []);
  useEffect(() => () => shapes.forEach(({ geometry, edges }) => { geometry.dispose(); edges.dispose(); }), [shapes]);

  useFrame(({ camera, size }, delta) => {
    if (!frozen) elapsed.current += Math.min(delta, 0.1);
    const time = elapsed.current;
    const height = 2 * Math.tan(camera.fov * Math.PI / 360) * 8;
    root.current.position.copy(camera.position);
    root.current.quaternion.copy(camera.quaternion);
    root.current.translateZ(-8);
    root.current.scale.setScalar(height);
    for (let index = 0; index < root.current.children.length; index++) {
      const object = root.current.children[index];
      const [x, y] = OBJECTS[index];
      object.position.set(x * size.width / size.height + Math.sin(time * 0.11 + index) * 0.008,
        y + Math.cos(time * 0.09 + index) * 0.008, 0);
      object.rotation.set(index * 0.6 + time * 0.035, index * 0.8 + time * 0.025, index * 0.4);
    }
  });

  return (
    <group ref={root} name="floating-objects">
      {OBJECTS.map(([, , scale], index) => (
        <group key={index} scale={scale}>
          <mesh geometry={shapes[index % 2].geometry} renderOrder={20}>
            <meshBasicMaterial color="#1A1A1A" />
          </mesh>
          <lineSegments geometry={shapes[index % 2].edges} renderOrder={21}>
            <lineBasicMaterial color="#FFFFFF" transparent opacity={0.18} depthWrite={false} />
          </lineSegments>
        </group>
      ))}
    </group>
  );
}

