import { useEffect, useLayoutEffect, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Matrix4 } from 'three';
import { useScrollStore } from '@/stores/useScrollStore';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { useSectionAnchor } from '@/3d/hooks/useSectionAnchor';
import { orbitalSkills } from '@/data/skills';

function Satellites({ count, radius, name }) {
  const mesh = useRef(null);
  useLayoutEffect(() => {
    const matrix = new Matrix4();
    for (let index = 0; index < count; index++) {
      const angle = index / count * Math.PI * 2;
      matrix.makeTranslation(Math.cos(angle) * radius, Math.sin(angle) * radius, 0);
      mesh.current.setMatrixAt(index, matrix);
    }
    mesh.current.instanceMatrix.needsUpdate = true;
    mesh.current.computeBoundingSphere();
  }, [count, radius]);
  return (
    <instancedMesh ref={mesh} name={name} args={[undefined, undefined, count]}>
      <octahedronGeometry args={[0.14, 0]} />
      <meshBasicMaterial color="#BBBBBB" toneMapped={false} />
    </instancedMesh>
  );
}

function Orbit({ anchor, frozen, quality }) {
  const root = useSectionAnchor(anchor, 2.7, frozen);
  const inner = useRef(null);
  const outer = useRef(null);
  const pause = useRef(null);
  useEffect(() => {
    pause.current = anchor.current?.querySelector('[data-orbit-pause]');
    return () => { pause.current = null; };
  }, [anchor]);

  useFrame((_, delta) => {
    if (!root.current?.visible) return;
    if (!frozen && !pause.current?.checked) {
      inner.current.rotation.z += Math.min(delta, 0.1) * 0.16;
      outer.current.rotation.z -= Math.min(delta, 0.1) * 0.1;
    }
  });

  return (
    <group ref={root} name="orbital-skills" visible={false}>
      <mesh name="skills-core">
        <icosahedronGeometry args={[0.28, quality === 'low' ? 0 : 1]} />
        <meshBasicMaterial color="#FFFFFF" toneMapped={false} />
      </mesh>
      {[{ radius: 1.65, count: 6, tilt: 0.72, ref: inner, name: 'skills-tools' },
        { radius: 2.55, count: orbitalSkills.length - 6, tilt: -0.55, ref: outer, name: 'skills-technical' }].map((ring) => (
        <group key={ring.name} rotation={[ring.tilt, 0, 0.2]}>
          <group ref={ring.ref}>
            <mesh>
              <torusGeometry args={[ring.radius, 0.009, 4, quality === 'low' ? 32 : quality === 'medium' ? 48 : 64]} />
              <meshBasicMaterial color="#BBBBBB" transparent opacity={0.3} depthWrite={false} toneMapped={false} />
            </mesh>
            <Satellites count={ring.count} radius={ring.radius} name={ring.name} />
          </group>
        </group>
      ))}
    </group>
  );
}

export function OrbitalSkills({ anchor, quality = 'high' }) {
  const active = useScrollStore((state) => state.currentSection === 'skills');
  const frozen = useReducedMotion();
  return active ? <Orbit anchor={anchor} frozen={frozen} quality={quality} /> : null;
}

