import { useEffect, useMemo, useRef, useState } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { Vector2 } from 'three';
import { useTranslation } from 'react-i18next';
import { SceneBoundary } from '@/3d/components/SceneBoundary';
import { SceneFallback } from '@/3d/components/SceneFallback';
import { useReducedMotion } from '@/hooks/useReducedMotion';

const vertex = /* glsl */ `
  uniform vec2 uPointer;
  uniform float uStrength;
  varying float vLight;
  void main() {
    vec3 p = position;
    vec2 away = p.xy - uPointer;
    float distance = length(away);
    float force = exp(-distance * distance * 1.8) * uStrength;
    p.xy += away / max(distance, 0.05) * force * 1.1;
    vLight = 0.7 + force * 0.3;
    gl_PointSize = 2.0;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
  }
`;
const fragment = /* glsl */ `
  varying float vLight;
  void main() {
    float core = 1.0 - smoothstep(0.1, 0.5, length(gl_PointCoord - 0.5));
    gl_FragColor = vec4(vec3(1.0), core * vLight);
  }
`;

function Field({ pulse, frozen }) {
  const material = useRef(null);
  const { invalidate, viewport } = useThree();
  const uniforms = useMemo(() => ({ uPointer: { value: new Vector2() }, uStrength: { value: 0 } }), []);
  const positions = useMemo(() => Float32Array.from({ length: 600 * 3 }, (_, i) => {
    const index = Math.floor(i / 3);
    return i % 3 === 0 ? Math.cos(index * 2.39996) * Math.sqrt(index / 600) * 4.8
      : i % 3 === 1 ? Math.sin(index * 2.39996) * Math.sqrt(index / 600) * 2.6 : 0;
  }), []);
  useEffect(() => {
    material.current.uniforms.uPointer.value.set(0, 0);
    material.current.uniforms.uStrength.value = frozen || !pulse ? 0 : 1;
    invalidate();
  }, [pulse, frozen, invalidate]);
  useFrame((_, delta) => {
    const strength = material.current.uniforms.uStrength;
    strength.value *= Math.exp(-Math.min(delta, 0.032) * 6);
    if (strength.value > 0.002) invalidate();
    else strength.value = 0;
  });
  const push = (event) => {
    if (frozen) return;
    material.current.uniforms.uPointer.value.set(event.point.x, event.point.y);
    material.current.uniforms.uStrength.value = 1;
    invalidate();
  };
  return (
    <>
      <points name="demo-particles" frustumCulled={false}>
        <bufferGeometry><bufferAttribute attach="attributes-position" args={[positions, 3]} /></bufferGeometry>
        <shaderMaterial ref={material} vertexShader={vertex} fragmentShader={fragment} uniforms={uniforms} transparent depthWrite={false} toneMapped={false} />
      </points>
      <mesh onPointerMove={push} onPointerDown={push} position={[0, 0, 0.1]}>
        <planeGeometry args={[viewport.width, viewport.height]} />
        <meshBasicMaterial transparent opacity={0} depthWrite={false} />
      </mesh>
    </>
  );
}

export function ParticleFieldDemo() {
  const { t } = useTranslation();
  const frozen = useReducedMotion();
  const [pulse, setPulse] = useState(0);
  return (
    <div className="relative h-full text-white">
      <SceneBoundary>
        <Canvas orthographic camera={{ position: [0, 0, 10], zoom: 55 }} dpr={1} frameloop="demand" gl={{ antialias: false }} aria-hidden="true" fallback={<SceneFallback />}>
          <Field pulse={pulse} frozen={frozen} />
        </Canvas>
      </SceneBoundary>
      <div className="absolute inset-x-4 bottom-4 flex items-center justify-between gap-3">
        <p className="max-w-[60%] font-mono text-xs leading-relaxed text-white/70">{t(`playground.demo.${frozen ? 'frozen' : 'particleHint'}`)}</p>
        <button type="button" disabled={frozen} onClick={() => setPulse(value => value + 1)} className="min-h-11 shrink-0 cursor-pointer border border-white/40 bg-black/80 px-3 font-mono text-xs hover:bg-white hover:text-black focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white disabled:cursor-default disabled:opacity-40">{t('playground.demo.push')}</button>
      </div>
    </div>
  );
}

