import { useEffect, useMemo, useRef, useState } from 'react';
import { Canvas, useThree } from '@react-three/fiber';
import { useTranslation } from 'react-i18next';
import { SceneBoundary } from '@/3d/components/SceneBoundary';
import { SceneFallback } from '@/3d/components/SceneFallback';
import { useReducedMotion } from '@/hooks/useReducedMotion';

const vertex = /* glsl */ `
  varying vec2 vUv;
  void main() { vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }
`;
// Same value-noise/fbm as the lab's Nebula, without a running time uniform.
const fragment = /* glsl */ `
  uniform float uScale;
  uniform float uWarp;
  varying vec2 vUv;
  float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
  float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1, 0)), u.x),
               mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), u.x), u.y);
  }
  float fbm(vec2 p) {
    float value = 0.0, amplitude = 0.5;
    for (int i = 0; i < 5; i++) {
      value += amplitude * noise(p);
      p = p * 2.03 + vec2(1.7, 9.2); amplitude *= 0.5;
    }
    return value;
  }
  void main() {
    vec2 p = vUv * uScale;
    float f = fbm(p), g = fbm(p * 2.1 - f * uWarp);
    float shade = mix(0.025, 0.75, smoothstep(0.2, 0.8, g));
    gl_FragColor = vec4(vec3(shade), 1.0);
  }
`;

function Surface({ scale, warp }) {
  const material = useRef(null);
  const invalidate = useThree(state => state.invalidate);
  const uniforms = useMemo(() => ({ uScale: { value: 3.2 }, uWarp: { value: 0.7 } }), []);
  useEffect(() => {
    material.current.uniforms.uScale.value = scale;
    material.current.uniforms.uWarp.value = warp;
    invalidate();
  }, [scale, warp, invalidate]);
  return (
    <mesh name="demo-fbm">
      <planeGeometry args={[2, 2]} />
      <shaderMaterial ref={material} vertexShader={vertex} fragmentShader={fragment} uniforms={uniforms} toneMapped={false} />
    </mesh>
  );
}

export function ShaderPlaygroundDemo() {
  const { t } = useTranslation();
  const frozen = useReducedMotion();
  const [scale, setScale] = useState(3.2);
  const [warp, setWarp] = useState(0.7);
  return (
    <div className="relative h-full text-white">
      <SceneBoundary>
        <Canvas dpr={1} frameloop="demand" gl={{ antialias: false }} aria-hidden="true" fallback={<SceneFallback />}>
          <Surface scale={scale} warp={warp} />
        </Canvas>
      </SceneBoundary>
      <fieldset disabled={frozen} className="absolute inset-x-4 bottom-4 grid grid-cols-2 gap-x-4 bg-black/85 p-3 font-mono text-xs">
        <legend className="sr-only">{t('playground.demo.shaderControls')}</legend>
        {[[ 'scale', scale, setScale, 1, 8 ], [ 'warp', warp, setWarp, 0, 2 ]].map(([key, value, change, min, max]) => (
          <label key={key} className="flex min-w-0 flex-col gap-1">
            <span className="flex justify-between gap-2">{t(`playground.demo.${key}`)}<output>{value.toFixed(1)}</output></span>
            <input type="range" min={min} max={max} step="0.1" value={value} onChange={event => change(Number(event.target.value))} className="h-11 w-full cursor-pointer accent-white focus-visible:outline-2 focus-visible:outline-white disabled:cursor-default disabled:opacity-40" />
          </label>
        ))}
      </fieldset>
