import { useEffect, useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { BufferAttribute, BufferGeometry, DynamicDrawUsage } from 'three';
import { advanceShootingStars, createShootingStars, METEOR_SAMPLES } from '@/3d/utils/shootingStars';

const VERTEX = /* glsl */ `
  attribute float aAlpha;
  uniform float uPixelRatio;
  varying float vAlpha;
  void main() {
    vAlpha = aAlpha;
    gl_PointSize = uPixelRatio * (1.0 + aAlpha * 1.5);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;
const FRAGMENT = /* glsl */ `
  varying float vAlpha;
  void main() {
    float core = 1.0 - smoothstep(0.1, 0.5, length(gl_PointCoord - 0.5));
    gl_FragColor = vec4(vec3(1.0), vAlpha * core);
  }
`;

export function ShootingStars() {
  const root = useRef(null);
  const pool = useMemo(() => createShootingStars(), []);
  const uniforms = useMemo(() => ({ uPixelRatio: { value: 1 } }), []);
  const geometry = useMemo(() => {
    const result = new BufferGeometry();
    result.setAttribute('position', new BufferAttribute(new Float32Array(3 * METEOR_SAMPLES * 3), 3).setUsage(DynamicDrawUsage));
    result.setAttribute('aAlpha', new BufferAttribute(new Float32Array(3 * METEOR_SAMPLES), 1).setUsage(DynamicDrawUsage));
    return result;
  }, []);
  useEffect(() => () => geometry.dispose(), [geometry]);

  useFrame(({ camera, gl, size }, delta) => {
    const height = 2 * Math.tan(camera.fov * Math.PI / 360) * 12;
    root.current.position.copy(camera.position);
    root.current.quaternion.copy(camera.quaternion);
    root.current.translateZ(-12);
    root.current.scale.setScalar(height);
    const { position, aAlpha } = root.current.geometry.attributes;
    advanceShootingStars(pool, delta, size.width / size.height, position.array, aAlpha.array);
    position.needsUpdate = aAlpha.needsUpdate = true;
    root.current.material.uniforms.uPixelRatio.value = gl.getPixelRatio();
  });

  return (
    <points ref={root} name="shooting-stars" geometry={geometry} frustumCulled={false} renderOrder={20}>
      <shaderMaterial vertexShader={VERTEX} fragmentShader={FRAGMENT} uniforms={uniforms} transparent depthWrite={false} />
    </points>
  );
}

