import { gsap, ScrollSmoother, ScrollTrigger, useGSAPSetup } from '@/hooks/useGSAPSetup';
import { useScrollStore } from '@/stores/useScrollStore';

export function useScrollProgress({ scope } = {}) {
  useGSAPSetup(() => {
    const content = document.getElementById('smooth-content');
    if (!content) return;

    let sections = [];
    const { setProgress, setCurrentSection } = useScrollStore.getState();

    const update = () => {
      if (ScrollTrigger.isRefreshing) return;
      // Publish the visible DOM position, including the smoother's settling frames.
      const scroll = ScrollSmoother.get()?.scrollTop() ?? window.scrollY;
      const maxScroll = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
      const progress = maxScroll > 0 ? scroll / maxScroll : 0;
      const readingLine = scroll + window.innerHeight * 0.35;
      let currentSection = 'hero';

      for (const section of sections) {
        if (section.top > readingLine) break;
        currentSection = section.id;
      }

      const state = useScrollStore.getState();
      const clampedProgress = Math.min(1, Math.max(0, progress));
      if (state.scrollProgress !== clampedProgress) setProgress(clampedProgress);
      if (state.currentSection !== currentSection) setCurrentSection(currentSection);
    };

    const measure = () => {
      const contentTop = content.getBoundingClientRect().top;
      sections = Array.from(content.querySelectorAll('section[id], footer[id]'), (element) => ({
        id: element.id,
        // Relative coordinates survive both smooth transforms and native-scroll restoration.
        top: element.getBoundingClientRect().top - contentTop,
      })).sort((a, b) => a.top - b.top);
      update();
    };

    measure();
    // Smoother's local refresh and content reflow can change section positions.
    const resizeObserver = new ResizeObserver(measure);
    resizeObserver.observe(content);
    // Added after GSAP's root update, so ScrollSmoother has rendered this tick.
    gsap.ticker.add(update);
    window.addEventListener('resize', measure);
    window.addEventListener('load', measure);
    ScrollTrigger.addEventListener('refresh', measure);

    return () => {
      resizeObserver.disconnect();
      gsap.ticker.remove(update);
      window.removeEventListener('resize', measure);
      window.removeEventListener('load', measure);
      ScrollTrigger.removeEventListener('refresh', measure);
    };
  }, { scope });
}

src/3d/hooks/useSectionAnchor.js:
import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { ScrollTrigger, useGSAPSetup } from '@/hooks/useGSAPSetup';
import { useScrollStore } from '@/stores/useScrollStore';

// Fit a decorative model into its DOM window, including ScrollSmoother transforms.
export function useSectionAnchor(anchor, radius, frozen) {
  const root = useRef(null);
  const reveal = useRef(0.96);
  const bounds = useRef({ left: 0, top: 0, width: 0, height: 0 });

  useGSAPSetup(() => {
    const content = document.getElementById('smooth-content');
    const element = anchor.current;
    if (!content || !element) return;
    const measure = () => {
      const rect = element.getBoundingClientRect();
      bounds.current.left = rect.left;
      bounds.current.top = rect.top - content.getBoundingClientRect().top;
      bounds.current.width = rect.width;
      bounds.current.height = rect.height;
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(content);
    observer.observe(element);
    window.addEventListener('resize', measure);
    ScrollTrigger.addEventListener('refresh', measure);
    return () => {
      observer.disconnect();
      window.removeEventListener('resize', measure);
      ScrollTrigger.removeEventListener('refresh', measure);
    };
  }, { scope: anchor });

  useFrame(({ camera }, delta) => {
    if (!root.current) return;
    const rect = bounds.current;
    const scroll = useScrollStore.getState().scrollProgress * Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
    const top = rect.top - scroll;
    // Canvas CSS resizes before R3F's ResizeObserver publishes its new size.
    const width = window.innerWidth;
    const viewportHeight = window.innerHeight;
    root.current.visible = rect.width > 0 && rect.height > 0
      && top + rect.height > 0 && top < viewportHeight;
    if (!root.current.visible) return;

    const distance = 8;
    const height = 2 * Math.tan(camera.fov * Math.PI / 360) * distance;
    root.current.position.set(
      ((rect.left + rect.width / 2) / width - 0.5) * height * camera.aspect,
      (0.5 - (top + rect.height / 2) / viewportHeight) * height,
      -distance,
    ).applyQuaternion(camera.quaternion).add(camera.position);
    root.current.quaternion.copy(camera.quaternion);
    reveal.current = frozen ? 1 : reveal.current + (1 - reveal.current) * (1 - Math.exp(-5 * Math.min(delta, 0.1)));
    root.current.scale.setScalar(Math.min(rect.width, rect.height) * 0.4 * height / viewportHeight / radius * reveal.current);
  });

  return root;
}

