import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';

const demos = {
  starfieldExplorer: lazy(() => import('@/3d/components/ParticleFieldDemo').then(module => ({ default: module.ParticleFieldDemo }))),
  nebulaShaderPlayground: lazy(() => import('@/3d/components/ShaderPlaygroundDemo').then(module => ({ default: module.ShaderPlaygroundDemo }))),
  scrollProgressOrbit: lazy(() => import('@/components/effects/ScrollOrbitDemo').then(module => ({ default: module.ScrollOrbitDemo }))),
};

export function LiveDemo({ children, title, kind }) {
  const root = useRef(null);
  const [active, setActive] = useState(false);
  const { t } = useTranslation();
  const Demo = demos[kind];
  useEffect(() => {
    let inView = false;
    const update = () => setActive(inView && !document.hidden);
    const observer = new IntersectionObserver(([entry]) => {
      inView = entry.isIntersecting;
      update();
    });
    observer.observe(root.current);
    document.addEventListener('visibilitychange', update);
    return () => {
      observer.disconnect();
      document.removeEventListener('visibilitychange', update);
    };
  }, []);
  const placeholder = <p className="flex h-full items-center justify-center px-4 pt-8 font-mono text-xs text-white/70">{t('playground.demo.ready')}</p>;

  return (
    <div ref={root} data-live-demo={kind} role="group" aria-label={title} className="relative aspect-video min-h-64 overflow-clip border border-white/15 bg-(--bg-void) [background-image:linear-gradient(rgba(255,255,255,0.025)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.025)_1px,transparent_1px)] [background-size:32px_32px]">
      <div className="pointer-events-none absolute inset-x-4 top-4 z-10 flex items-start justify-between gap-4 bg-black/85 px-2 py-1 font-mono text-[10px] leading-relaxed tracking-[0.12em] text-white/80 sm:text-xs">
        <span className="max-w-[75%]">{title}</span>
        <span lang="en" className="text-(--text-primary)">{t('playground.liveLabel')}</span>
      </div>
      {Demo ? (active ? <Suspense fallback={placeholder}><Demo /></Suspense> : placeholder) : children ?? (
        <div className="flex h-full items-center justify-center px-4 pt-8">
          <button type="button" disabled className="min-h-11 cursor-default border border-white/20 px-4 py-2 font-mono text-xs text-(--text-secondary)">
            {t('playground.comingSoon')}
          </button>
        </div>
      )}
    </div>
  );
}

