import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';

export function ScrollOrbitDemo() {
  const root = useRef(null);
  const scrollTrigger = useRef(null);
  const { t } = useTranslation();
  const frozen = useReducedMotion();
  useGSAP(() => {
    if (frozen) return;
    const q = gsap.utils.selector(root);
    const ring = q('[data-demo-orbit]');
    const bar = q('[data-demo-progress]');
    const timeline = gsap.timeline({ scrollTrigger: {
      id: 'playground-scroll-demo', trigger: root.current,
      start: 'clamp(top bottom)', end: 'clamp(bottom top)', scrub: 0.35,
    } }).fromTo(ring, { rotation: 0 }, { rotation: 360, ease: 'none' }, 0)
      .fromTo(bar, { scaleX: 0 }, { scaleX: 1, ease: 'none' }, 0);
    scrollTrigger.current = timeline.scrollTrigger;
  }, { scope: root, dependencies: [frozen], revertOnUpdate: true });
  const tryOrbit = () => {
    if (frozen) return;
    const trigger = scrollTrigger.current;
    if (trigger) {
      const forward = trigger.progress < 0.5;
      const scroll = trigger.start + (trigger.end - trigger.start) * (forward ? 0.7 : 0.3);
      trigger.scroll(scroll);
    }
  };
  return (
    <div ref={root} className="relative flex h-full items-center justify-center text-white">
      <div className="pointer-events-none relative size-28 sm:size-32" aria-hidden="true">
        <div className="absolute inset-0 rounded-full border border-white/25" />
        <div className="absolute inset-4 rounded-full border border-dashed border-white/10" />
        <div className="absolute inset-0 flex items-center justify-center"><span className="size-3 rounded-full bg-white/80" /></div>
        <div data-demo-orbit className="absolute inset-0"><span className="absolute top-1/2 -left-1 size-2 rounded-full bg-white" /></div>
      </div>
      <div className="absolute inset-x-4 bottom-4 flex items-center gap-4">
        <div className="flex min-w-0 flex-1 flex-col gap-2 font-mono text-xs text-white/70">
          <p>{t(`playground.demo.${frozen ? 'frozen' : 'scrollHint'}`)}</p>
          <div className="h-0.5 overflow-hidden bg-white/15" aria-hidden="true"><div data-demo-progress className={`h-full origin-left bg-white ${frozen ? 'scale-x-50' : 'scale-x-0'}`} /></div>
        </div>
        <button type="button" disabled={frozen} onClick={tryOrbit} className="min-h-11 shrink-0 cursor-pointer border border-white/40 bg-black/80 px-3 font-mono text-xs hover:bg-white hover:text-black focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white disabled:cursor-default disabled:opacity-40">{t('playground.demo.scrollTry')}</button>
      </div>
    </div>
  );
}

