import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { Mail, Facebook, Linkedin, Globe } from 'lucide-react';
import { gsap, splitText } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';

export default function Footer() {
  const root = useRef(null);
  const { t, i18n } = useTranslation();
  const reducedMotion = useReducedMotion();
  const heading = t('contact.heading');
  const words = heading.split(' ');
  const email = t('contact.email');

  const { contextSafe } = useGSAP(
    () => {
      if (reducedMotion) return;
      const q = gsap.utils.selector(root.current);
      const split = splitText(q('.footer-big'), {
        type: 'chars, words',
        charsClass: 'split-char',
        smartWrap: true,
        aria: 'none',
      });

      gsap.fromTo(
        split.chars,
        { y: 60, autoAlpha: 0, rotation: 3 },
        {
          y: 0,
          autoAlpha: 1,
          rotation: 0,
          duration: 0.8,
          ease: 'expo.out',
          stagger: { each: 0.03, from: 'start' },
          scrollTrigger: {
            trigger: q('.footer-big'),
            start: 'top 88%',
            toggleActions: 'play none none reverse',
          },
        }
      );

      gsap.fromTo(
        q('.footer-fade'),
        { y: 24, autoAlpha: 0 },
        {
          y: 0,
          autoAlpha: 1,
          duration: 0.7,
          ease: 'power3.out',
          stagger: 0.08,
          scrollTrigger: {
            trigger: q('.footer-grid'),
            start: 'top 85%',
            toggleActions: 'play none none reverse',
          },
        }
      );

      return () => split.revert();
    },
    { scope: root, dependencies: [i18n.resolvedLanguage, reducedMotion], revertOnUpdate: true }
  );

  const scrambleMail = contextSafe((e) => {
    if (reducedMotion) return;
    gsap.to(e.currentTarget.querySelector('.mail-text'), {
      duration: 0.6,
      ease: 'none',
      scrambleText: { text: email, chars: 'upperAndLowerCase', revealDelay: 0.2 },
      overwrite: 'auto',
    });
  });

  return (
    <footer
      ref={root}
      id="site-footer"
      data-theme="dark"
      aria-label={t('footer.copyright')}
      className="relative z-10 overflow-hidden border-t border-white/[0.08] bg-(--bg-void) px-6 py-20 text-(--text-primary) sm:px-8 md:px-12 md:py-28 lg:px-16"
    >
      <div className="footer-grid mx-auto flex max-w-[1600px] flex-col justify-between gap-12 xl:flex-row xl:items-end">
        <h2
          key={i18n.resolvedLanguage}
          aria-label={heading}
          className="footer-big min-w-0 font-display text-[clamp(2.5rem,6.5vw,6.5rem)] font-bold uppercase leading-[1.1] tracking-[-0.035em] text-(--text-primary)"
        >
          {words.slice(0, -1).join(' ')}{' '}
          <span className="stroke-text-white whitespace-nowrap">{words.at(-1)}</span>
        </h2>

        <div className="flex flex-col items-start gap-5 xl:shrink-0 xl:items-end">
          <a
            href={t('contact.emailUrl')}
            aria-label={email}
            onMouseEnter={scrambleMail}
            data-magnetic
            className="footer-fade group flex max-w-full items-center gap-3 rounded-full border border-white/15 bg-white/[0.02] px-6 py-3 font-mono text-sm font-medium text-(--text-primary) transition-all hover:border-white/40 hover:bg-white/[0.06] hover:text-white sm:text-base will-transform"
          >
            <Mail size={18} className="shrink-0 text-(--text-secondary) transition-colors group-hover:text-white" />
            <span className="mail-text min-w-0 [overflow-wrap:anywhere]" aria-hidden="true">
              {email}
            </span>
          </a>

          <a
            href={`tel:${t('contact.phone').replace(/\s/g, '')}`}
            className="footer-fade inline-flex min-h-11 items-center font-mono text-sm text-(--text-secondary) transition-colors hover:text-(--text-primary)"
          >
            {t('contact.phone')}
          </a>

          <div className="footer-fade flex items-center gap-3">
            <a
              href={t('contact.facebookUrl')}
              target="_blank"
              rel="noopener noreferrer"
              aria-label={t('contact.facebookLabel')}
              className="flex h-11 w-11 items-center justify-center rounded-full border border-white/10 bg-white/[0.02] text-(--text-secondary) transition-all hover:border-white/35 hover:bg-white/[0.06] hover:text-white"
            >
              <Facebook size={18} />
            </a>

            <a
              href={t('contact.linkedinUrl') || undefined}
              target="_blank"
              rel="noopener noreferrer"
              aria-label={t('contact.linkedinLabel')}
              aria-disabled={!t('contact.linkedinUrl') || undefined}
              title={t('contact.linkedinUrl') ? undefined : t('nav.socialPending')}
              className={`flex h-11 w-11 items-center justify-center rounded-full border border-white/10 bg-white/[0.02] transition-all ${
                t('contact.linkedinUrl')
                  ? 'text-(--text-secondary) hover:border-white/35 hover:bg-white/[0.06] hover:text-white'
                  : 'cursor-default text-(--text-muted) opacity-40'
              }`}
            >
              <Linkedin size={18} />
            </a>

            <a
              href={t('footer.websiteUrl') || undefined}
              target="_blank"
              rel="noopener noreferrer"
              aria-label={t('footer.websiteLabel')}
              aria-disabled={!t('footer.websiteUrl') || undefined}
              title={t('footer.websiteUrl') ? undefined : t('nav.socialPending')}
              className={`flex h-11 w-11 items-center justify-center rounded-full border border-white/10 bg-white/[0.02] transition-all ${
                t('footer.websiteUrl')
                  ? 'text-(--text-secondary) hover:border-white/35 hover:bg-white/[0.06] hover:text-white'
                  : 'cursor-default text-(--text-muted) opacity-40'
              }`}
            >
              <Globe size={18} />
            </a>
          </div>
        </div>
      </div>

      <div className="mx-auto mt-16 flex max-w-[1600px] flex-col items-center justify-between gap-4 border-t border-white/[0.08] pt-8 font-mono text-xs uppercase tracking-wider text-(--text-secondary) sm:flex-row sm:flex-wrap">
        <span>{t('footer.copyright')}</span>
        <span className="hidden text-(--text-muted) md:inline">{t('footer.disciplines')}</span>
        <span className="text-(--text-secondary)">{t('footer.buildCredit', { version: '3.15' })}</span>
      </div>
    </footer>
  );
}

src/components/Hero.jsx:
import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, splitText } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';

export default function Hero({ active }) {
  const root = useRef(null);
  const { t } = useTranslation();
  const reducedMotion = useReducedMotion();
  const name = t('hero.name');
  const words = name.split(' ');
  const tagline = t('hero.tagline');
  const subTagline = t('hero.subTagline');
  const scrollIndicator = t('hero.scrollIndicator');

  useGSAP((context, contextSafe) => {
    const q = gsap.utils.selector(root);
    const [content] = q('[data-hero-content]');
    if (!active) {
      gsap.set(content, { autoAlpha: 0 });
      return;
    }
    if (reducedMotion) return;

    gsap.set(q('[data-hero-intro]'), { autoAlpha: 0 });
    gsap.fromTo(content, { autoAlpha: 1, scale: 1 }, {
      autoAlpha: 0, scale: 0.94, ease: 'none',
      scrollTrigger: {
        id: 'hero-exit', trigger: root.current,
        start: 'top top', end: 'bottom top', scrub: 1,
      },
    });

    let mounted = true;
    const startIntro = contextSafe(() => {
      if (!mounted) return;
      const split = splitText(q('[data-hero-name]'), {
        type: 'chars', smartWrap: true, charsClass: 'hero-char', aria: 'none',
      });
      const intro = gsap.timeline({ id: 'hero-intro', defaults: { ease: 'expo.out' } });
      intro.addLabel('name', 1.5).addLabel('tagline', 2).addLabel('subTagline', 2.3).addLabel('indicator', 2.5);
      intro.set(q('[data-hero-name]'), { autoAlpha: 1 }, 'name');
      intro.fromTo(split.chars, { y: 40, autoAlpha: 0 }, {
        y: 0, autoAlpha: 1, duration: 0.9, stagger: 0.03,
      }, 'name');
      intro.fromTo(q('[data-hero-tagline]'), { y: 40, autoAlpha: 0 }, {
        y: 0, autoAlpha: 1, duration: 1,
      }, 'tagline');
      intro.to(q('[data-hero-scramble]'), {
        duration: 1.2, ease: 'none',
        scrambleText: { text: tagline, chars: 'upperAndLowerCase', revealDelay: 0.15 },
      }, 'tagline');
      intro.fromTo(q('[data-hero-sub]'), { y: 40, autoAlpha: 0 }, {
        y: 0, autoAlpha: 1, duration: 1,
      }, 'subTagline');
      intro.fromTo(q('[data-hero-scroll]'), { y: 40, autoAlpha: 0 }, {
        y: 0, autoAlpha: 1, duration: 0.8,
      }, 'indicator');
      gsap.to(q('[data-hero-chevron]'), {
        y: 6, opacity: 0.35, duration: 1.2, delay: 3.1, ease: 'sine.inOut', repeat: -1, yoyo: true,
        scrollTrigger: {
          id: 'hero-indicator', trigger: root.current, start: 'top bottom', end: 'bottom top',
          toggleActions: 'play pause resume pause',
        },
      });
    });
    document.fonts.ready.then(startIntro);
    return () => { mounted = false; };
  }, { scope: root, dependencies: [active, reducedMotion, name, tagline, subTagline, scrollIndicator], revertOnUpdate: true });

  return (
    <section
      ref={root} id="hero" aria-labelledby="hero-heading"
      className="relative z-10 flex min-h-screen flex-col bg-transparent text-(--text-primary) pointer-events-none supports-[height:100dvh]:min-h-dvh"
    >
      <div data-hero-content className="relative flex w-full flex-1 flex-col items-center justify-center px-[max(1rem,env(safe-area-inset-left),env(safe-area-inset-right))] pt-[calc(7rem+env(safe-area-inset-top))] pb-[calc(10rem+env(safe-area-inset-bottom))] text-center sm:px-6 md:px-12">
        <h1
          key={name} id="hero-heading" data-hero-name data-hero-intro aria-label={name}
          className="w-full font-display text-[clamp(44px,12vw,200px)] font-extrabold leading-[1.04] tracking-[-0.02em] [font-kerning:none] [text-rendering:optimizeSpeed]"
        >
