import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, ScrollTrigger, revealHeadings } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { useScrollStore } from '@/stores/useScrollStore';

export default function Contact() {
  const root = useRef(null);
  const { t, i18n } = useTranslation();
  const reducedMotion = useReducedMotion();
  const language = i18n.resolvedLanguage;

  useGSAP((context, contextSafe) => {
    const { setContactProgress } = useScrollStore.getState();
    setContactProgress(0);
    if (!reducedMotion) {
      revealHeadings(root.current.querySelectorAll('[data-contact-line]'), contextSafe);
      const phase = { progress: 0 };
      gsap.timeline({
        defaults: { ease: 'none' },
        scrollTrigger: {
          id: 'contact-approach', trigger: root.current,
          start: 'top bottom', end: 'top 15%', scrub: 0.45,
        },
        onUpdate: () => setContactProgress(phase.progress),
      }).to(phase, { progress: 1, duration: 1.4 }, 0)
        .fromTo('[data-contact-line]', { y: 40, opacity: 0 }, {
          y: 0, opacity: 1, duration: 1, stagger: 0.1, ease: 'expo.out',
        }, 0.3)
        .fromTo('[data-contact-copy]', { y: 40, opacity: 0 }, {
          y: 0, opacity: 1, duration: 0.8, stagger: 0.1, ease: 'power3.out',
        }, 0.3);
      // Composite the button's fixed shadow; never tween box-shadow or the magnetic target.
      gsap.fromTo('[data-contact-glow]', { opacity: 0.12 }, {
        opacity: 0.38, duration: 2.4, repeat: -1, yoyo: true, ease: 'sine.inOut',
        scrollTrigger: {
          trigger: '[data-contact-email]', start: 'top bottom', end: 'bottom top',
          toggleActions: 'play pause resume pause',
        },
      });
    }
    ScrollTrigger.refresh(true);
    return () => setContactProgress(0);
  }, { scope: root, dependencies: [reducedMotion, language], revertOnUpdate: true });

  const linkStyle = 'inline-flex min-h-11 items-center py-2 text-(--text-secondary) hover:text-(--text-primary) focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-white';

  return (
    <section
      ref={root}
      id="transmission"
      lang={language}
      data-theme="dark"
      aria-labelledby="transmission-heading"
