    >
      <div className="mx-auto max-w-7xl">
        <p data-contact-copy lang="en" className="mb-10 flex items-center gap-4 font-mono text-xs tracking-[0.2em] text-(--text-secondary)">
          <span aria-hidden="true" className="h-px w-10 bg-white/30" />
          {t('contact.sectionLabel')}
        </p>
        <h2 key={language} aria-label={`${t('contact.heading')} ${t('contact.alternateHeading')}`} id="transmission-heading" className="font-display text-[clamp(1.35rem,7vw,7rem)] font-bold leading-[1.25] tracking-[-0.045em]">
          <span className="block overflow-clip">
            <span data-contact-line className="split-heading block whitespace-nowrap motion-safe:opacity-0">{t('contact.heading')}</span>
          </span>
          <span className="block overflow-clip">
            <span data-contact-line lang={language === 'vi' ? 'en' : 'vi'} className="split-heading stroke-text-white block whitespace-nowrap motion-safe:opacity-0">{t('contact.alternateHeading')}</span>
          </span>
        </h2>
        <p data-contact-copy className="mt-8 max-w-xl font-body text-lg leading-relaxed text-(--text-secondary) sm:text-xl">
          {t('contact.subHeading')}
        </p>

        <div data-contact-copy className="mt-12 sm:mt-16">
          <a
            data-contact-email
            data-magnetic
            href={t('contact.emailUrl')}
            className="cta-hover relative inline-flex min-h-18 w-full items-center justify-center gap-6 rounded-full border border-transparent bg-(--text-primary) px-8 py-6 font-display text-xs font-semibold tracking-[0.06em] text-black shadow-(--glow-button) focus-visible:outline-2 focus-visible:outline-offset-8 focus-visible:outline-white sm:w-auto sm:px-10 sm:text-sm"
          >
            <span data-contact-glow aria-hidden="true" className="pointer-events-none absolute inset-0 rounded-full opacity-15 shadow-(--glow-button)" />
            <span className="relative">{t('contact.emailCta')}</span>
            <svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" fill="none" className="relative h-5 w-5 shrink-0 stroke-current stroke-[1.5]">
              <path d="M5 19 19 5M5 5h14v14" />
            </svg>
          </a>
        </div>

        <div data-contact-copy className="mt-16 flex flex-col gap-4 border-t border-white/10 bg-(--bg-void)/90 px-4 py-6 font-mono text-xs sm:flex-row sm:flex-wrap sm:items-center sm:gap-x-10 sm:text-sm lg:mt-24">
          <a href={t('contact.emailUrl')} className={`${linkStyle} [overflow-wrap:anywhere]`}>{t('contact.email')}</a>
