import { useRef, useState } from 'react';
import { flushSync } from 'react-dom';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, Flip, ScrollTrigger, revealHeadings } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { PORTFOLIO_DATA } from '@/data';

const filters = [
  ['all', null],
  ['productDesign', 'Product Design'],
  ['uxUi', 'UX/UI Design'],
  ['graphic', 'Graphic Design'],
];
const projectKeys = ['eduraLms', 'verisApp', 'viePerfume'];
const focusRing = 'focus-visible:outline-2 focus-visible:outline-white focus-visible:outline-offset-4';

export default function Work() {
  const root = useRef(null);
  const [filter, setFilter] = useState('all');
  const reducedMotion = useReducedMotion();
  const { t, i18n } = useTranslation();
  const category = filters.find(([key]) => key === filter)[1];
  const { contextSafe } = useGSAP({ scope: root });

  useGSAP((context, contextSafe) => {
    // Finish a filter transition before locale/motion rebuilds measure the grid.
    Flip.killFlipsOf(root.current.querySelectorAll('[data-project-grid], [data-project-card]'), true);
    if (reducedMotion) {
      ScrollTrigger.refresh(true);
      return;
    }
    revealHeadings(root.current.querySelectorAll('h2,h3'), contextSafe);
    const intro = gsap.utils.toArray('[data-works-intro]', root.current)
      .filter((element) => element.getBoundingClientRect().top >= innerHeight * 0.85);
    if (intro.length) {
      gsap.fromTo(intro, { y: 40, opacity: 0 }, {
        y: 0, opacity: 1, duration: 1, stagger: 0.1, ease: 'power3.out',
        scrollTrigger: {
          id: 'works-heading-reveal', trigger: intro[0], start: 'top 85%', once: true,
        },
      });
    }
    gsap.utils.toArray('[data-project-card]:not(.hidden)', root.current).forEach((card) => {
      gsap.fromTo(card.querySelector('[data-project-image]'),
        { clipPath: 'inset(12% 8%)' },
        {
          clipPath: 'inset(0% 0%)', duration: 1, ease: 'none',
          scrollTrigger: {
            id: `works-image-reveal-${card.dataset.flipId}`, trigger: card,
            start: 'top 92%', end: 'top 45%', scrub: 0.8,
          },
        });
      gsap.timeline({
        scrollTrigger: {
          id: `works-reveal-${card.dataset.flipId}`,
          trigger: card,
          start: 'top 92%',
          end: 'top 45%',
          scrub: 0.35,
          invalidateOnRefresh: true,
        },
      })
        .fromTo(card.querySelectorAll('[data-project-text]'),
          { y: 40, opacity: 0 },
          { y: 0, opacity: 1, stagger: 0.1, duration: 0.9, ease: 'power3.out' }, 0.15);
    });
    ScrollTrigger.refresh(true);
  }, { scope: root, dependencies: [filter, reducedMotion, i18n.resolvedLanguage], revertOnUpdate: true });

  function changeFilter(next) {
    if (next === filter) return;
    const grid = root.current.querySelector('[data-project-grid]');
    const cards = gsap.utils.toArray('[data-project-card]', root.current);
    const state = reducedMotion ? null : Flip.getState([grid, ...cards]);
    // Commit React's display changes before Flip measures the final grid.
    flushSync(() => setFilter(next));
    if (!state) {
      ScrollTrigger.refresh(true);
      return;
    }
    contextSafe(() => {
      Flip.from(state, {
        duration: 0.6,
        ease: 'power3.inOut',
        absolute: cards,
        nested: true,
        scale: false,
        onEnter: (elements) => gsap.fromTo(elements, { opacity: 0 }, { opacity: 1, duration: 0.4 }),
        onLeave: (elements) => gsap.to(elements, { opacity: 0, duration: 0.2 }),
        onComplete: () => ScrollTrigger.refresh(true),
      });
    })();
  }

  return (
    <section ref={root} id="work" aria-labelledby="works-heading" className="relative bg-(--bg-void) px-5 py-24 text-(--text-primary) sm:px-8 md:px-12 md:py-36">
      <div className="mx-auto max-w-[1600px]">
        <header className="mb-12 md:mb-20">
          <p data-works-intro className="mb-6 font-mono text-label text-(--text-secondary)">{t('works.sectionLabel')}</p>
          <h2 key={i18n.resolvedLanguage} aria-label={t('works.heading')} id="works-heading" className="split-heading max-w-[13ch] text-balance [overflow-wrap:anywhere] font-display text-[clamp(1.5rem,8vw,8rem)] leading-[1.12] font-bold tracking-[-0.04em]">{t('works.heading')}</h2>
          <div data-works-intro role="group" aria-label={t('works.filterLabel')} className="mt-10 flex flex-wrap gap-2 border-t border-white/10 pt-6 md:mt-14">
            {filters.map(([key]) => (
              <button
                key={key}
                type="button"
                data-magnetic
                aria-pressed={filter === key}
                aria-controls="works-grid"
                onClick={() => changeFilter(key)}
                className={`min-h-11 min-w-11 cursor-pointer border px-4 py-2 font-body text-sm transition-colors motion-reduce:transition-none ${focusRing} ${filter === key ? 'border-white bg-(--text-primary) text-(--bg-void)' : 'border-white/10 text-(--text-secondary) hover:border-white/35 hover:text-(--text-primary)'}`}
              >
                {t(`works.filters.${key}`)}
              </button>
            ))}
          </div>
        </header>

        <div id="works-grid" data-project-grid className="relative grid grid-cols-12 gap-x-6 gap-y-16 md:gap-y-28">
          {PORTFOLIO_DATA.projects.map((project, index) => {
            const key = projectKeys[index];
            const path = `works.projects.${key}`;
            const visible = !category || project.category === category;
            const Content = project.link ? 'a' : 'div';
            return (
              <article
                key={project.id}
                data-project-card
                data-flip-id={`project-${project.id}`}
                data-cursor={project.link ? 'view' : 'default'}
                aria-hidden={!visible}
                inert={!visible}
                className={`works-card group min-w-0 col-span-12 ${index % 2 === 0 ? 'md:col-span-8 md:col-start-1' : 'md:col-span-7 md:col-start-6'} ${visible ? '' : 'hidden'}`}
              >
                <Content
                  href={project.link}
                  target={project.link ? '_blank' : undefined}
                  rel={project.link ? 'noopener noreferrer' : undefined}
                  aria-labelledby={project.link ? `project-title-${project.id}` : undefined}
                  data-hover-card
                  className={`hover-card block h-full border border-white/10 bg-(--bg-nebula) ${project.link ? focusRing : 'cursor-default'}`}
                >
                  <div data-project-image className="reveal-clip relative aspect-[16/10] overflow-clip">
                    <img
                      src={project.imageUrl}
                      alt={t(`${path}.title`)}
                      width="1600"
                      height="1000"
                      loading="lazy"
                      decoding="async"
                      className="h-full w-full object-cover"
                    />
                    <div aria-hidden="true" className="pointer-events-none absolute inset-0 bg-linear-to-t from-black/40 to-transparent opacity-0 transition-opacity duration-100 motion-safe:group-hover:opacity-100 motion-safe:group-focus-within:opacity-100 motion-reduce:transition-none" />
                  </div>
                  <div className="p-5 sm:p-7 md:p-8">
                    <div data-project-text className="mb-5 flex items-center justify-between gap-4 font-mono text-label text-(--text-secondary)">
                      <span>{t(`${path}.category`)}</span>
                      <span aria-hidden="true">{project.id}</span>
                    </div>
                    <h3 key={i18n.resolvedLanguage} aria-label={t(`${path}.title`)} id={`project-title-${project.id}`} className="split-heading font-display text-[clamp(1.25rem,3.2vw,3.5rem)] leading-tight font-semibold tracking-[-0.03em]">{t(`${path}.title`)}</h3>
                    <p data-project-text className="mt-5 max-w-[54ch] font-body text-base leading-relaxed text-(--text-secondary)">{t(`${path}.description`)}</p>
                    <ul data-project-text className="mt-6 flex flex-wrap gap-2" aria-label={t('works.tagsLabel')}>
                      {t(`${path}.tags`, { returnObjects: true }).map((tag) => (
                        <li key={tag} className="rounded-full border border-white/10 px-3 py-1 font-mono text-xs text-(--text-secondary)">{tag}</li>
                      ))}
                    </ul>
                    <div data-project-text className="mt-8">
                      {project.link ? (
                        <span className="inline-flex min-h-11 items-center gap-3 border-b border-white/35 font-mono text-label uppercase">{t('works.viewCaseStudy')}<span aria-hidden="true">↗</span></span>
                      ) : (
                        <button type="button" disabled className="min-h-11 cursor-default border border-white/20 px-3 py-2 text-left font-mono text-xs uppercase text-(--text-secondary)">{t(`${path}.caseStudyLabel`)}</button>
                      )}
                    </div>
                  </div>
                </Content>
              </article>
            );
          })}
        </div>
      </div>
    </section>
  );
}

