import gsap from 'gsap';
import { useGSAP } from '@gsap/react';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { ScrollSmoother } from 'gsap/ScrollSmoother';
import { SplitText } from 'gsap/SplitText';
import { ScrambleTextPlugin } from 'gsap/ScrambleTextPlugin';
import { ScrollToPlugin } from 'gsap/ScrollToPlugin';
import { Flip } from 'gsap/Flip';
import { DrawSVGPlugin } from 'gsap/DrawSVGPlugin';

// Module initialization runs once, before React's effects (including StrictMode).
gsap.registerPlugin(useGSAP, ScrollTrigger, ScrollSmoother, SplitText, ScrambleTextPlugin, ScrollToPlugin, Flip, DrawSVGPlugin);
gsap.defaults({ duration: 0.6, ease: 'power2.out' });

export function useGSAPSetup(callback, config) {
  return useGSAP(callback, config);
}

/**
 * Call inside useGSAP/useGSAPSetup, gsap.matchMedia, or a contextSafe callback.
 * SplitText joins that GSAP context and automatically reverts on cleanup.
 * Pass `type` to split only the units you need; the returned instance also has revert().
 */
export function splitText(source, opts = {}) {
  return SplitText.create(source, {
    linesClass: 'split-line',
    charsClass: 'split-char',
    ...opts,
  });
}

/** Call in the owning useGSAP context, after guarding reduced motion. */
export function revealHeadings(targets, contextSafe, scroll = true) {
  Array.from(targets).filter((target) => target.getClientRects().length).forEach((target) => {
    const pending = !scroll || target.getBoundingClientRect().top >= window.innerHeight * 0.85;
    splitText(target, {
      type: 'lines,chars', autoSplit: true,
      onSplit: contextSafe((split) => pending ? gsap.fromTo(split.chars,
        { y: 40, opacity: 0 },
        {
          y: 0, opacity: 1, duration: 0.8, ease: 'expo.out', stagger: 0.03,
          ...(scroll ? { scrollTrigger: { trigger: target, start: 'top 85%', once: true } } : {}),
        }) : gsap.set(split.chars, { y: 0, opacity: 1 })),
    });
  });
}

export { gsap, ScrollTrigger, ScrollSmoother, SplitText, ScrambleTextPlugin, ScrollToPlugin, Flip, DrawSVGPlugin };

src/hooks/useReducedMotion.js:
import { useSyncExternalStore } from 'react';

const motionQuery = typeof window !== 'undefined'
  ? window.matchMedia('(prefers-reduced-motion: reduce)')
  : null;

function subscribe(onChange) {
  motionQuery?.addEventListener('change', onChange);
  return () => motionQuery?.removeEventListener('change', onChange);
}

const getSnapshot = () => motionQuery?.matches ?? false;
const getServerSnapshot = () => false;

export function useReducedMotion() {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

src/hooks/useSmoothScroll.js:
import { useGSAP } from '@gsap/react';
import { gsap, ScrollSmoother } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';

export function useSmoothScroll({ scope, paused = false } = {}) {
  const reducedMotion = useReducedMotion();

  useGSAP(() => {
    const media = gsap.matchMedia(scope);

    media.add('(prefers-reduced-motion: no-preference)', () => {
      if (ScrollSmoother.get()) return;

      ScrollSmoother.create({
        wrapper: '#smooth-wrapper',
        content: '#smooth-content',
        smooth: 1.2,
        // The cropped avatar owns its bounded scrub; never drive its y twice.
        effects: '[data-speed]:not([data-parallax="crop"]), [data-lag]',
        normalizeScroll: true,
        ignoreMobileResize: true,
      });
      // ScrollSmoother.revert() is kill(): matchMedia owns this instance.
    });

    // Kills the owned smoother on unmount and on StrictMode's cleanup pass.
    // matchMedia also reverts immediately when reduced motion is enabled.
    return () => media.revert();
  }, { scope });

  useGSAP(() => {
    ScrollSmoother.get()?.paused(paused);
  }, { scope, dependencies: [paused, reducedMotion], revertOnUpdate: true });
}

src/i18n/config.js:
import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import vi from '@/i18n/locales/vi.json';
import en from '@/i18n/locales/en.json';
import { useLangStore } from '@/stores/useLangStore';

i18n.use(initReactI18next).init({
  lng: useLangStore.getState().lang, // The store defaults to 'vi'.
  fallbackLng: 'en',
  supportedLngs: ['vi', 'en'],
  resources: {
    vi: { translation: vi },
    en: { translation: en },
  },
  interpolation: { escapeValue: false },
});

// Store → i18n only: languageChanged never writes back into the store.
const unsubscribe = useLangStore.subscribe(({ lang }) => {
  if (i18n.language !== lang) i18n.changeLanguage(lang);
});

const META_COPY = {
  vi: {
    title: 'Trần Vũ Anh Duy — Creative Designer · Stellar Odyssey Portfolio',
    description: 'Trần Vũ Anh Duy — Creative Designer chuyên về UX/UI, Motion Graphics và 3D Web tương tác. Trải nghiệm không gian vũ trụ điện ảnh, tối giản và hướng tới người dùng.',
  },
  en: {
    title: 'Tran Vu Anh Duy — Creative Designer · Stellar Odyssey Portfolio',
    description: 'Portfolio of Tran Vu Anh Duy — Creative Designer specializing in UX/UI, Motion Graphics, and interactive 3D Web. Minimalist, cinematic, user-centric portfolio experience.',
  },
};

function applyLanguage(lang) {
  if (typeof document === 'undefined') return;
  document.documentElement.lang = lang;
  const copy = META_COPY[lang] || META_COPY.vi;
  document.title = copy.title;
  const metaDesc = document.querySelector('meta[name="description"]');
  if (metaDesc) metaDesc.setAttribute('content', copy.description);
}
applyLanguage(i18n.resolvedLanguage);
i18n.on('languageChanged', applyLanguage);

if (import.meta.hot) import.meta.hot.dispose(() => {
  unsubscribe();
  i18n.off('languageChanged', applyLanguage);
});

export { i18n };
export default i18n;

