src/index.css:
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500&family=JetBrains+Mono:wght@400&display=swap');
@import 'tailwindcss';
@import 'tw-animate-css';
@import './styles/globals.css';

@layer base {
  * {
    border-color: var(--color-border);
    outline-color: var(--color-foreground);
  }

  html {
    background: var(--color-background);
    scrollbar-width: thin;
    scrollbar-color: var(--color-secondary) var(--color-background);
    overscroll-behavior: none;
  }

  html.lenis-lock,
  body.loading-lock {
    overflow: hidden;
  }

  body {
    background: var(--color-background);
    color: var(--color-foreground);
    -webkit-font-smoothing: antialiased;
  }

  ::selection {
    background: var(--color-foreground);
    color: var(--color-background);
  }

  ::-webkit-scrollbar { width: 8px; }
  ::-webkit-scrollbar-track { background: var(--color-background); }
  ::-webkit-scrollbar-thumb { background: var(--color-secondary); }
}

/* ScrollSmoother: fixed nav/cursor/preloader stay outside the wrapper. */
#smooth-wrapper { overflow: clip; }
#smooth-content { will-change: transform; }

/* WIP compatibility: existing JSX keeps this display-font class until Phase 2. */
.font-syne { font-family: var(--font-display); }

/* Preserve the WIP's outline text on its explicitly light/dark sections. */
.stroke-text {
  -webkit-text-stroke: 1px var(--bg-elevated);
  color: transparent;
}
.stroke-text-white {
  -webkit-text-stroke: 1px color-mix(in srgb, var(--text-primary) 80%, transparent);
  color: transparent;
}
.stroke-text-bg {
  -webkit-text-stroke: 2px color-mix(in srgb, var(--bg-elevated) 28%, transparent);
  color: transparent;
}

.will-transform { will-change: transform; }
.will-fade { will-change: transform, opacity; }
.gsap-cursor-dot,
.gsap-cursor-ring {
  will-change: transform;
  pointer-events: none;
}

/* Static noise: no animated filters or extra compositing hints. */
.noise::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 60;
  pointer-events: none;
  opacity: 0.05;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

.split-line { overflow: clip; display: block; }
.split-char { display: inline-block; }
.split-heading { font-kerning: none; text-rendering: optimizeSpeed; }
.reveal-clip { clip-path: inset(0 0 0 0); }

/* Apply to the inner surface: scroll entrances and Flip own its parent. */
.hover-card {
  transition: border-color 120ms ease-out;
}

.hover-card:focus-within,
.cta-hover:focus-visible {
  border-color: rgb(250 250 250 / 0.35);
}

@media (hover: hover) and (pointer: fine) {
  .hover-card:hover,
  .cta-hover:hover {
    border-color: rgb(250 250 250 / 0.35);
  }

  @media (prefers-reduced-motion: no-preference) {
    .hover-card {
      transition: border-color 120ms ease-out, transform 140ms cubic-bezier(0.22, 1, 0.36, 1);
    }

    .hover-card:hover {
      transform: translateY(-4px) scale(1.05);
    }

    .cta-hover:hover,
    .cta-hover:focus-visible {
      box-shadow: var(--glow-button-strong);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  #smooth-content,
  .will-transform,
  .will-fade,
  .gsap-cursor-dot,
  .gsap-cursor-ring,
  .split-char {
    will-change: auto;
  }
}

