import { create } from 'zustand';

export const useScrollStore = create((set) => ({
  scrollProgress: 0,
  currentSection: 'hero',
  contactProgress: 0,
  setContactProgress: (progress) => {
    if (Number.isFinite(progress)) {
      const value = Math.min(1, Math.max(0, progress));
      set((state) => state.contactProgress === value ? state : { contactProgress: value });
    }
  },
  // The scroll bridge supplies progress; CameraRig consumes it without measuring again.
  setProgress: (progress) => {
    if (Number.isFinite(progress)) {
      set({ scrollProgress: Math.min(1, Math.max(0, progress)) });
    }
  },
  setCurrentSection: (currentSection) => set({ currentSection }),
}));

src/stores/useThemeStore.js:
import { create } from 'zustand';

export const useThemeStore = create((set, get) => ({
  // The head bootstrap resolves storage/OS before React renders. SSR stays dark.
  theme: typeof document !== 'undefined' && document.documentElement.dataset.theme === 'light' ? 'light' : 'dark',
  toggleTheme: () => get().setTheme(get().theme === 'dark' ? 'light' : 'dark'),
  setTheme: (theme) => {
    if (theme !== 'dark' && theme !== 'light') return;
    set({ theme });
    get().applyTheme();
  },
  applyTheme: () => {
    if (typeof document === 'undefined') return;
    const { theme } = get();
    if (theme === 'light') document.documentElement.setAttribute('data-theme', 'light');
    else document.documentElement.removeAttribute('data-theme');

    let meta = document.querySelector('meta[name="theme-color"]');
    if (!meta) {
      meta = document.createElement('meta');
      meta.name = 'theme-color';
      document.head.append(meta);
    }
    meta.content = theme === 'light' ? '#FAFAFA' : '#050505';
    try {
      window.localStorage.setItem('stellar-theme', theme);
    } catch { /* Keep the toggle usable when persistence is unavailable. */ }
  },
}));

src/styles/globals.css:
/* Stellar Odyssey — source of truth: kế-hoạch.md, sections 4.1 and 4.2. */
@layer base {
  /* 1. Primitives: keep the approved dark palette invariant across themes. */
  :root {
    --bg-void: #050505;
    --bg-nebula: #0A0A0A;
    --bg-surface: #111111;
    --bg-elevated: #1A1A1A;
    --text-primary: #FAFAFA;
    --text-secondary: #999999;
    --text-muted: #555555;

    /* Button/CTA only. No card, text, or ambient glow tokens. */
    --glow-button: 0 0 30px rgba(255,255,255,0.35);
    --glow-button-strong: 0 0 50px rgba(255,255,255,0.55);

    /* Only the additional light values explicitly specified in section 4.1. */
    --bg-void-light: #FAFAFA;
    --bg-nebula-light: #F2F2F2;
    --bg-surface-light: #FFFFFF;
    --text-primary-light: #111111;
    --text-secondary-light: #666666;
  }

  /* 2. Semantic roles: Tailwind's inline aliases resolve these in each scope. */
  :root,
  [data-theme='dark'] {
    color-scheme: dark;
    --surface-background: var(--bg-void);
    --surface-nebula: var(--bg-nebula);
    --surface-card: var(--bg-surface);
    --surface-elevated: var(--bg-elevated);
    --foreground-primary: var(--text-primary);
    --foreground-secondary: var(--text-secondary);
    --foreground-muted: var(--text-muted);
    --border-default: var(--bg-elevated);
    --accent-default: var(--text-primary);
    --glow-button: 0 0 30px rgba(255,255,255,0.35);
    --glow-button-strong: 0 0 50px rgba(255,255,255,0.55);
  }

  [data-theme='light'] {
    color-scheme: light;
    --surface-background: var(--bg-void-light);
    --surface-nebula: var(--bg-nebula-light);
    --surface-card: var(--bg-surface-light);
    /* No separate light elevated/muted values were specified; reuse the palette. */
    --surface-elevated: var(--bg-nebula-light);
    --foreground-primary: var(--text-primary-light);
    --foreground-secondary: var(--text-secondary-light);
    --foreground-muted: var(--text-muted);
    --border-default: var(--text-secondary-light);
    --accent-default: var(--text-primary-light);
    --glow-button: 0 0 20px rgba(0,0,0,0.25);
    /* The spec defines one light glow; both button states reuse that value. */
    --glow-button-strong: var(--glow-button);
  }

  /* Re-resolve public aliases at theme boundaries for scoped previews as well
   * as root themes. Inherited custom properties otherwise keep the parent value.
   */
  :root,
  [data-theme] {
    --color-background: var(--surface-background);
    --color-nebula: var(--surface-nebula);
    --color-card: var(--surface-card);
    --color-elevated: var(--surface-elevated);
    --color-foreground: var(--foreground-primary);
    --color-secondary: var(--foreground-secondary);
    --color-muted: var(--foreground-muted);
    --color-border: var(--border-default);
    --color-accent: var(--accent-default);
  }
}

/* Static keeps the full public token API even before Phase 2 consumes utilities.
 * Inline references semantic roles, so bg-background/text-foreground follow
 * data-theme on the root or on a scoped preview without a JS theme toggle.
 */
@theme inline static {
  --color-background: var(--surface-background);
  --color-nebula: var(--surface-nebula);
  --color-card: var(--surface-card);
  --color-elevated: var(--surface-elevated);
  --color-foreground: var(--foreground-primary);
  --color-secondary: var(--foreground-secondary);
  --color-muted: var(--foreground-muted);
  --color-border: var(--border-default);
  --color-accent: var(--accent-default);

  /* Fontsource registers the Unbounded family as "Unbounded Variable".
   * Its bundled Vietnamese and Latin subsets supply the actual display face.
   */
  --font-display: 'Unbounded Variable', 'Unbounded', sans-serif;
  --font-body: 'Space Grotesk', sans-serif;
  --font-sans: var(--font-body);
  --font-mono: 'JetBrains Mono', monospace;

  /* Section 4.2 defines ranges, not individual h1–h6 sizes. These steps stay
   * within the display range (4rem–12vw); WIP utilities override base rules.
   */
  --text-h1: max(4rem, 12vw);
  --text-h2: max(4rem, 8vw);
  --text-h3: max(4rem, 6vw);
  --text-h4: max(4rem, 5vw);
  --text-h5: max(4rem, 4.5vw);
  --text-h6: 4rem;
  --text-body: 1rem;
  --text-body-lg: 1.25rem;
  --text-label: 0.875rem;
  --text-body--line-height: 1.6;
  --text-body-lg--line-height: 1.6;
  --text-label--line-height: 1.5;
  --text-label--font-weight: 400;
}

@layer base {
  html {
    font-family: var(--font-body);
  }

  body {
    font-family: var(--font-body);
    font-size: var(--text-body);
    font-weight: 400;
    line-height: var(--text-body--line-height);
  }

  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
    font-weight: 600;
    line-height: 1.1;
    letter-spacing: -0.02em;
  }
  h1 { font-size: var(--text-h1); font-weight: 800; }
  h2 { font-size: var(--text-h2); font-weight: 700; }
  h3 { font-size: var(--text-h3); }
  h4 { font-size: var(--text-h4); }
  h5 { font-size: var(--text-h5); }
  h6 { font-size: var(--text-h6); }

  p {
    font-size: var(--text-body);
    line-height: var(--text-body--line-height);
  }

  label, code, kbd, samp {
    font-family: var(--font-mono);
    font-size: var(--text-label);
    font-weight: 400;
    line-height: var(--text-label--line-height);
  }
}

/* 3. Component layer: reserved hooks. Styling and UI belong to Phase 2. */
@layer components {
  .btn-glow { /* Phase 2: button/CTA only. */ }
  .card { /* Phase 2: semantic surface/border, no glow. */ }
  .section-heading { /* Phase 2: display typography. */ }
}

